int x25_negotiate_facilities(struct sk_buff *skb, struct sock *sk,
                             struct x25_facilities *new,
                             struct x25_dte_facilities *dte)
{
    struct x25_facilities facilities;
    u8 *ptr = skb->data;
    int length = 0;
    int reverse_charge;

    /* Initialize the facilities structures */
    memset(&facilities, 0, sizeof(facilities));
    memset(new, 0, sizeof(*new));
    memset(dte, 0, sizeof(*dte));

    /* Parse incoming facilities */
    if (skb->len < 2)
        return -EINVAL;

    facilities.throughput = *ptr++;
    facilities.packet_size = *ptr++;
    length += 2;

    if (skb->len < length + 2)
        return -EINVAL;

    facilities.window_size = *ptr++;
    facilities.reverse_charging = *ptr++;
    length += 2;

    reverse_charge = facilities.reverse_charging & 0x80;

    /* Negotiate throughput */
    new->throughput = min(facilities.throughput, sk->sk_rcvbuf >> 10);

    /* Negotiate packet size */
    new->packet_size = min(facilities.packet_size, X25_DEFAULT_PACKET_SIZE);

    /* Negotiate window size */
    new->window_size = min(facilities.window_size, X25_DEFAULT_WINDOW_SIZE);

    /* Set reverse charging flag */
    if (reverse_charge)
        new->flags |= X25_FAC_REVERSE_CHARGE;

    /* Set DTE facilities */
    dte->throughput = facilities.throughput;
    dte->packet_size = facilities.packet_size;
    dte->window_size = facilities.window_size;

    /* Log debug messages */
    if (reverse_charge)
        printk(KERN_DEBUG "X.25: Reverse charging requested by DCE\n");

    if (new->throughput != facilities.throughput)
        printk(KERN_DEBUG "X.25: Throughput downgraded from %d to %d\n",
               facilities.throughput, new->throughput);

    if (new->packet_size != facilities.packet_size)
        printk(KERN_DEBUG "X.25: Packet size downgraded from %d to %d\n",
               facilities.packet_size, new->packet_size);

    if (new->window_size != facilities.window_size)
        printk(KERN_DEBUG "X.25: Window size downgraded from %d to %d\n",
               facilities.window_size, new->window_size);

    return length;
}

int x25_negotiate_facilities(struct sk_buff *skb, struct sock *sk, struct x25_facilities *new, struct x25_dte_facilities *dte)
{
    struct x25_facilities incoming;
    unsigned char *ptr = skb->data;
    int length = 0;
    int i;

    memset(new, 0, sizeof(*new));
    memset(dte, 0, sizeof(*dte));
    memset(&incoming, 0, sizeof(incoming));

    for (i = 0; i < X25_MAX_FACILITIES; i++) {
        unsigned int facility;

        if (length + 1 > skb->len)
            return -EINVAL;

        facility = *ptr++;
        length++;

        switch (facility) {
        case X25_FACILITY_EOR:
            if (length + 1 > skb->len)
                return -EINVAL;
            new->reverse = *ptr++;
            length++;
            break;

        case X25_FACILITY_TOM:
            if (length + 1 > skb->len)
                return -EINVAL;
            incoming.throughput = *ptr++;
            length++;
            break;

        case X25_FACILITY_PSZ:
            if (length + 1 > skb->len)
                return -EINVAL;
            incoming.packet_size = *ptr++;
            length++;
            break;

        case X25_FACILITY_WINDOW:
            if (length + 1 > skb->len)
                return -EINVAL;
            incoming.window_size = *ptr++;
            length++;
            break;

        case X25_FACILITY_DTE:
            if (length + 1 > skb->len)
                return -EINVAL;
            dte->dte = *ptr++;
            length++;
            break;

        default:
            if (facility & 0x80) {
                /* Ignore unknown facilities */
                break;
            }

            if (length + 1 > skb->len)
                return -EINVAL;
            ptr++;
            length += 1;
            break;
        }
    }

    if (incoming.throughput > X25_DEFAULT_THROUGHPUT)
        new->throughput = min(incoming.throughput, sk->sk_type);
    else
        new->throughput = X25_DEFAULT_THROUGHPUT;

    if (incoming.packet_size > X25_DEFAULT_PACKET_SIZE)
        new->packet_size = min(incoming.packet_size, sk->sk_type);
    else
        new->packet_size = X25_DEFAULT_PACKET_SIZE;

    if (incoming.window_size > X25_DEFAULT_WINDOW_SIZE)
        new->window_size = min(incoming.window_size, sk->sk_type);
    else
        new->window_size = X25_DEFAULT_WINDOW_SIZE;

    if (new->reverse & X25_REVERSE_CHARGE_REQUEST)
        x25_log_reverse_charge_request(sk);

    return length;
}

int x25_negotiate_facilities(struct sk_buff *skb, struct sock *sk, struct x25_facilities *new,
                             struct x25_dte_facilities *dte)
{
    struct x25_facilities local;
    struct x25_facilities remote;
    unsigned char *ptr = skb->data;
    int len = skb->len;
    int i;

    x25_init_facilities(&local);
    x25_init_facilities(&remote);

    for (i = 0; i < len; i++) {
        switch (ptr[i]) {
        case X25_FACILITY_REVERSE_CHARGE:
            if (ptr[i+1] & 0x80)
                local.reverse_charging = 1;
            else
                local.reverse_charging = 0;
            break;
        case X25_FACILITY_THROUGHPUT:
            local.throughput = (ptr[i+1] >> 4) & 0x0F;
            remote.throughput = ptr[i+1] & 0x0F;
            break;
        case X25_FACILITY_PACKET_SIZE:
            local.packet_size = (ptr[i+1] >> 4) & 0x0F;
            remote.packet_size = ptr[i+1] & 0x0F;
            break;
        case X25_FACILITY_WINDOW_SIZE:
            local.window_size = (ptr[i+1] >> 4) & 0x0F;
            remote.window_size = ptr[i+1] & 0x0F;
            break;
        default:
            break;
        }
    }

    new->throughput = min(local.throughput, remote.throughput);
    new->packet_size = min(local.packet_size, remote.packet_size);
    new->window_size = min(local.window_size, remote.window_size);
    new->reverse_charging = local.reverse_charging || remote.reverse_charging;

    dte->throughput = new->throughput;
    dte->packet_size = new->packet_size;
    dte->window_size = new->window_size;

    x25_debug("Negotiated throughput: %d, packet size: %d, window size: %d, reverse charging: %d\n",
              new->throughput, new->packet_size, new->window_size, new->reverse_charging);

    return len;
}

int x25_negotiate_facilities(struct sk_buff *skb, struct sock *sk,
                             struct x25_facilities *new,
                             struct x25_dte_facilities *dte)
{
    struct x25_facilities local;
    unsigned char *ptr = skb->data;
    int length = 0;
    int i;

    memset(new, 0, sizeof(*new));
    local = *new;

    for (i = 0; i < X25_MAX_FACILITIES && ptr < skb_tail_pointer(skb); i++) {
        unsigned int facility = *ptr++;

        switch (facility) {
        case X25_FACILITY_REVERSE_CHARGE:
            new->reverse_charge = *ptr++;
            break;
        case X25_FACILITY_THROUGHPUT:
            new->throughput = *ptr++;
            break;
        case X25_FACILITY_PACKET_SIZE:
            new->window_size = *ptr++;
            break;
        case X25_FACILITY_WINDOW_SIZE:
            new->window_size = *ptr++;
            break;
        case X25_FACILITY_DTE:
            dte->reverse_charge = *ptr++;
            dte->throughput = *ptr++;
            dte->window_size = *ptr++;
            dte->packet_size = *ptr++;
            break;
        default:
            ptr++; /* Skip unknown facility */
            break;
        }

        length++;
    }

    if (new->throughput > local.throughput)
        new->throughput = local.throughput;

    if (new->window_size > local.window_size)
        new->window_size = local.window_size;

    if (new->packet_size > local.packet_size)
        new->packet_size = local.packet_size;

    if (new->reverse_charge != X25_REVERSE_CHARGE_DEFAULT)
        printk(KERN_DEBUG "X.25: Reverse charging requested\n");

    return length;
}

int x25_negotiate_facilities(struct sk_buff *skb, struct sock *sk,
                             struct x25_facilities *new,
                             struct x25_dte_facilities *dte)
{
    struct x25_facilities called, calling;
    int len = 0;
    u8 *ptr;

    memset(&called, 0, sizeof(struct x25_facilities));
    memset(&calling, 0, sizeof(struct x25_facilities));

    ptr = skb->data;

    if (*ptr != X25_CALL_REQUEST)
        return -EINVAL;

    ptr += 3;
    if (x25_facilities_decode(&called, &ptr, skb->data + skb->len))
        return -EINVAL;

    if (x25_facilities_decode(&calling, &ptr, skb->data + skb->len))
        return -EINVAL;

    len = ptr - skb->data;

    if (called.reverse_charging) {
        if (sk->sk_type == SOCK_DGRAM)
            return -EINVAL;
        new->reverse_charging = 1;
    }

    new->throughput = min_not_zero(called.throughput, calling.throughput);
    new->packet_size = min_not_zero(called.packet_size, calling.packet_size);
    new->window_size = min_not_zero(called.window_size, calling.window_size);

    dte->max_packet = htons(min_t(u16, ntohs(called.packet_size),
                                   ntohs(calling.packet_size)));

    return len;
}
